-- =====================================================================
--  初期の型紙2つ（CLUB Voice・共通フォーマット）を、コード（lib/setting_sheet.php の SHEET_TEMPLATES）から DB に移す
--  036_count_upcoming.sql まで流した DB（本番も含む）に、追加で流す。1回だけ流すこと（2回流すと2つずつ増える）
--
--  これで画面（sheet_templates.php）から普通の型紙と同じように編集できる。
--  コードの venue_words（会場名の一部一致）は無くなるので、その言葉を含む会場を sheet_template_venue でつなぐ。
--  created_by は NULL → 038 で最初の管理者にする
--  PDF・セット図の背景は assets/sheets/ のまま（差し替えても、uploads の外なので消されない）
-- =====================================================================
SET NAMES utf8mb4;

-- club_voice
INSERT INTO sheet_template (label, pdf_path, config) VALUES ('新大久保 CLUB Voice', 'assets/sheets/club_voice.pdf', '{"stage_image":"assets/sheets/club_voice_stage.png?v=2","fields":{"kana":{"box":[198,61,384,71],"size":8,"align":"left"},"band":{"box":[160,73,422,87.6],"size":14,"align":"left"},"date":{"box":[158.5,99,223.7,111],"size":10,"align":"center"},"order":{"box":[328.3,98,362,111],"size":13,"align":"center"}},"members":{"top":148.3,"row_h":20.875,"rows":8,"part":[57.7,89],"name":[89.9,255.2]},"stage":[265.2,138.4,498.4,300.1],"drum":[360.5,148.8,389.6,170.5],"gt_amps":["JC","Marshall","TwinReverb"],"setlist":{"top":371.4,"row_h":25.08,"rows":10,"no":[57.7,88.6],"title":[88.6,262.4],"sound":[262.4,388.7],"light":[388.7,499.2]},"extras_title":"その他","show_if":{"se_src":["se",["あり"]],"start":["se",["あり"]],"end":["se",["あり"]]},"choices":{"se":{"あり":[95.8,338,106.5,348.7],"なし":[126,338,144.1,348.7]},"se_src":{"iPhone":[186.7,338,219,348.7],"CD":[233,338,246.7,348.7]},"start":{"ハケ":[300.1,338,320.4,348.7],"板付":[344.7,338,366.1,348.7]},"end":{"手上げ":[398.2,338,429.7,348.7],"流し切り":[454.1,338,490.7,348.7]}},"choice_notes":{"start":{"ハケ":"開演前、ステージから人がハケた状態でSEを流します。","板付":"開演前、出演者がステージにいる状態でSEを流します。"}},"texts":[{"key":"se_track","label":"CD のトラック番号","box":[251,338,257.9,348.7],"size":10,"pad":0.2,"with_choice":"se_src","show_if":["se_src",["CD"]],"digits":true,"placeholder":"例: 3"}]}');
SET @tid = LAST_INSERT_ID();
INSERT IGNORE INTO sheet_template_venue (template_id, venue_id) SELECT @tid, venue_id FROM venue WHERE name LIKE '%Voice%' OR name LIKE '%VOICE%' OR name LIKE '%ボイス%';

