SET @tid = LAST_INSERT_ID();
INSERT IGNORE INTO sheet_template_venue (template_id, venue_id) SELECT @tid, venue_id FROM venue WHERE name LIKE '%和泉キャンパス%' OR name LIKE '%シェラリゾート%' OR name LIKE '%湯沢%' OR name LIKE '%ゆうげん荘%' OR name LIKE '%G-ROKS%';

